ion\":\"Value of the field. If the field is a checkbox, its value is the checked property. If the field is a Captcha, its value is the token property. If the field is a file upload, its value is an array of the uploaded files' type.\"},{\"name\":\"id\",\"slug\":\"id\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"The [`WixForms`](wix-crm.html#$w-wixforms) element's unique identifier. Used when selecting elements using the `$w()` selector.\"}]},\"WixForms.WixFormSubmitEventHandler\":{\"name\":\"WixFormSubmitEventHandler\",\"fqn\":\"WixForms.WixFormSubmitEventHandler\",\"slug\":\"wix-form-submit-event-handler\",\"actions\":[],\"properties\":[{\"name\":\"event\",\"slug\":\"event\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"WixFormSubmitEvent\",\"referenceFqn\":\"WixFormSubmitEvent.WixFormSubmitEvent\"},\"description\":\"The Wix Forms event that occurred.\"}],\"returnType\":{\"kind\":\"UNION\",\"types\":[{\"kind\":\"PRIMITIVE\",\"name\":\"object\"},{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"}],\"description\":\"Either an array of `WixFormField` objects, or a boolean value indicating if the Wix Form should be submitted to the server.\"}},\"WixFormSubmitEvent.WixFormSubmitEvent\":{\"name\":\"WixFormSubmitEvent\",\"fqn\":\"WixFormSubmitEvent.WixFormSubmitEvent\",\"slug\":\"wix-form-submit-event\",\"actions\":[],\"properties\":[{\"name\":\"context\",\"slug\":\"context\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the context of the event\",\"content\":\"// non-repeater event\\n\\n$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let type = event.context.type; // \\\"GLOBAL_SCOPE\\\"\\n} );\\n\\n\\n// repeater event\\n\\n$w(\\\"#myRepeatedElement\\\").onEvent( (event) =\u003e {\\n  let $item = $w.at(event.context)\\n  $item(\\\"#anotherRepeatedElement\\\").value = \\\"new value\\\";\\n\\n  let itemId = event.context.itemId;  // \\\"item1\\\"\\n} );\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventContext\",\"referenceFqn\":\"Event.EventContext\"},\"description\":\"Gets the context in which an event was fired.\\r\\n\\r\\nAn event's `context` contains information about the circumstances\\r\\n surrounding the firing of the event.\\r\\n The context property only appears in events on repeated elements.\\r\\n\\r\\n You can use the event context with [`$w.at()`]($w.html#at) to get a\\r\\n selector function which selects items from a specific repeater item.\\r\\n It contains an object with one key:value pair. The key is \\\"itemId\\\" and\\r\\n the value is the ID of the repeated item on which the event occurred.\"},{\"name\":\"target\",\"slug\":\"target\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the ID of the target element\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let targetId = event.target.id;  // \\\"myElement\\\"\\n} );\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\"},\"description\":\"Gets the element that the event was fired on.\"},{\"name\":\"type\",\"slug\":\"type\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the type of the event\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let eventType = event.type; // \\\"click\\\"\\n} );\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the type of event that was fired.\"},{\"name\":\"wixFormFields\",\"slug\":\"wix-form-fields\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"ARRAY\",\"elementType\":{\"kind\":\"REFERENCE\",\"name\":\"WixFormField\",\"referenceFqn\":\"WixFormSubmitEvent.WixFormField\"}},\"description\":\"An array of objects representing the fields on a Wix Form.\"}]},\"WixForms.WixFormSubmittedEventHandler\":{\"name\":\"WixFormSubmittedEventHandler\",\"fqn\":\"WixForms.WixFormSubmittedEventHandler\",\"slug\":\"wix-form-submitted-event-handler\",\"actions\":[],\"properties\":[{\"name\":\"event\",\"slug\":\"event\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"WixFormSubmittedEvent\",\"referenceFqn\":\"WixFormSubmittedEvent.WixFormSubmittedEvent\"},\"description\":\"The Wix Forms event that occurred.\"}],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}},\"WixFormSubmittedEvent.WixFormSubmittedEvent\":{\"name\":\"WixFormSubmittedEvent\",\"fqn\":\"WixFormSubmittedEvent.WixFormSubmittedEvent\",\"slug\":\"wix-form-submitted-event\",\"actions\":[],\"properties\":[{\"name\":\"context\",\"slug\":\"context\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the context of the event\",\"content\":\"// non-repeater event\\n\\n$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let type = event.context.type; // \\\"GLOBAL_SCOPE\\\"\\n} );\\n\\n\\n// repeater event\\n\\n$w(\\\"#myRepeatedElement\\\").onEvent( (event) =\u003e {\\n  let $item = $w.at(event.context)\\n  $item(\\\"#anotherRepeatedElement\\\").value = \\\"new value\\\";\\n\\n  let itemId = event.context.itemId;  // \\\"item1\\\"\\n} );\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventContext\",\"referenceFqn\":\"Event.EventContext\"},\"description\":\"Gets the context in which an event was fired.\\r\\n\\r\\nAn event's `context` contains information about the circumstances\\r\\n surrounding the firing of the event.\\r\\n The context property only appears in events on repeated elements.\\r\\n\\r\\n You can use the event context with [`$w.at()`]($w.html#at) to get a\\r\\n selector function which selects items from a specific repeater item.\\r\\n It contains an object with one key:value pair. The key is \\\"itemId\\\" and\\r\\n the value is the ID of the repeated item on which the event occurred.\"},{\"name\":\"target\",\"slug\":\"target\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the ID of the target element\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let targetId = event.target.id;  // \\\"myElement\\\"\\n} );\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\"},\"description\":\"Gets the element that the event was fired on.\"},{\"name\":\"type\",\"slug\":\"type\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the type of the event\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let eventType = event.type; // \\\"click\\\"\\n} );\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the type of event that was fired.\"},{\"name\":\"wixFormField\",\"slug\":\"wix-form-field\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"object\"},\"description\":\"An object representing a Wix Form field.\"}]},\"WixForms.WixFormSubmittedErrorEventHandler\":{\"name\":\"WixFormSubmittedErrorEventHandler\",\"fqn\":\"WixForms.WixFormSubmittedErrorEventHandler\",\"slug\":\"wix-form-submitted-error-event-handler\",\"actions\":[],\"properties\":[{\"name\":\"errorEvent\",\"slug\":\"error-event\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"WixFormSubmittedErrorEvent\",\"referenceFqn\":\"WixFormSubmittedErrorEvent.WixFormSubmittedErrorEvent\"},\"description\":\"The Wix Forms error event that occurred.\"}],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}},\"WixFormSubmittedErrorEvent.WixFormSubmittedErrorEvent\":{\"name\":\"WixFormSubmittedErrorEvent\",\"fqn\":\"WixFormSubmittedErrorEvent.WixFormSubmittedErrorEvent\",\"slug\":\"wix-form-submitted-error-event\",\"actions\":[],\"properties\":[{\"name\":\"code\",\"slug\":\"code\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the error code for a failed Wix Form submission.\"},{\"name\":\"context\",\"slug\":\"context\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the context of the event\",\"content\":\"// non-repeater event\\n\\n$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let type = event.context.type; // \\\"GLOBAL_SCOPE\\\"\\n} );\\n\\n\\n// repeater event\\n\\n$w(\\\"#myRepeatedElement\\\").onEvent( (event) =\u003e {\\n  let $item = $w.at(event.context)\\n  $item(\\\"#anotherRepeatedElement\\\").value = \\\"new value\\\";\\n\\n  let itemId = event.context.itemId;  // \\\"item1\\\"\\n} );\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventContext\",\"referenceFqn\":\"Event.EventContext\"},\"description\":\"Gets the context in which an event was fired.\\r\\n\\r\\nAn event's `context` contains information about the circumstances\\r\\n surrounding the firing of the event.\\r\\n The context property only appears in events on repeated elements.\\r\\n\\r\\n You can use the event context with [`$w.at()`]($w.html#at) to get a\\r\\n selector function which selects items from a specific repeater item.\\r\\n It contains an object with one key:value pair. The key is \\\"itemId\\\" and\\r\\n the value is the ID of the repeated item on which the event occurred.\"},{\"name\":\"message\",\"slug\":\"message\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the error message for a failed Wix Form submission.\"},{\"name\":\"target\",\"slug\":\"target\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the ID of the target element\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let targetId = event.target.id;  // \\\"myElement\\\"\\n} );\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\"},\"description\":\"Gets the element that the event was fired on.\"},{\"name\":\"type\",\"slug\":\"type\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the type of the event\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let eventType = event.type; // \\\"click\\\"\\n} );\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the type of event that was fired.\"}]},\"WixFormsV2.OnFieldValueChangeCallback\":{\"name\":\"OnFieldValueChangeCallback\",\"fqn\":\"WixFormsV2.OnFieldValueChangeCallback\",\"slug\":\"on-field-value-change-callback\",\"actions\":[],\"properties\":[{\"name\":\"formValues\",\"slug\":\"form-values\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"object\"},\"description\":\"An object containing information about field names and values of a form.\"}],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}},\"WixFormsV2.OnStepNumberChangeCallback\":{\"name\":\"OnStepNumberChangeCallback\",\"fqn\":\"WixFormsV2.OnStepNumberChangeCallback\",\"slug\":\"on-step-number-change-callback\",\"actions\":[],\"properties\":[{\"name\":\"currentStepNumber\",\"slug\":\"current-step-number\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"number\"},\"description\":\"The current step number which form navigated to.\"}],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}},\"WixFormsV2.OnSubmitCallback\":{\"name\":\"OnSubmitCallback\",\"fqn\":\"WixFormsV2.OnSubmitCallback\",\"slug\":\"on-submit-callback\",\"actions\":[],\"properties\":[{\"name\":\"formValues\",\"slug\":\"form-values\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"object\"},\"description\":\"An object containing information about field names and values of a form.\"}],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}},\"WixFormsV2.OnSubmitFailureCallback\":{\"name\":\"OnSubmitFailureCallback\",\"fqn\":\"WixFormsV2.OnSubmitFailureCallback\",\"slug\":\"on-submit-failure-callback\",\"actions\":[],\"properties\":[{\"name\":\"error\",\"slug\":\"error\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"SubmissionError\",\"referenceFqn\":\"WixFormsV2.SubmissionError\"},\"description\":\"Submission error.\"}],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}},\"WixFormsV2.SubmissionError\":{\"name\":\"SubmissionError\",\"fqn\":\"WixFormsV2.SubmissionError\",\"slug\":\"submission-error\",\"actions\":[],\"properties\":[{\"name\":\"code\",\"slug\":\"code\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Error code.\"},{\"name\":\"message\",\"slug\":\"message\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Error message.\"}]},\"WixFormsV2.OnSubmitSuccessCallback\":{\"name\":\"OnSubmitSuccessCallback\",\"fqn\":\"WixFormsV2.OnSubmitSuccessCallback\",\"slug\":\"on-submit-success-callback\",\"actions\":[],\"properties\":[],\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"}}},\"standaloneTypes\":[],\"metadata\":{},\"actions\":[{\"name\":\"$w\",\"fqn\":\"$w\",\"slug\":\"$w\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"selector\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"UNION\",\"types\":[{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\"},{\"kind\":\"ARRAY\",\"elementType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\"}}],\"description\":\"A single selected element or an array of selected elements.\"},\"examples\":[{\"title\":\"Select an element using its ID\",\"content\":\"let myElement = $w(\\\"#myElement\\\");\\n\\nlet elementType = myElement.type; // \\\"$w.Type\\\"\"},{\"title\":\"Select elements by type\",\"content\":\"let typeElements = $w(\\\"Type\\\");\\n\\nlet firstOfType = typeElements[0];\"},{\"title\":\"Select all the images on the page\",\"content\":\"let imageElements = $w(\\\"Image\\\");\\n\\nlet firstImage = imageElements[0];\"},{\"title\":\"Select elements using multiple selectors\",\"content\":\"let selected = $w(\\\"#myElement1, #myElement3, Type\\\");\"},{\"title\":\"Hide all the page's images\",\"content\":\"$w(\\\"Image\\\").hide();\"},{\"title\":\"Change an element's text\",\"description\":\"This example shows how to use `$w` to change an element's text when the page is loaded and when a button is clicked. You can test out the code in our [example template](https://manage.wix.com/edit-template/from?originTemplateId=387453c2-d335-4654-92d7-b0432adff4ac\u0026templateId=9fc970e6-8379-4dfb-9a62-9092b86607eb\u0026autoDevMode=true).\",\"content\":\"$w.onReady(function () {\\n  $w('#helloText').text = 'HELLO WORLD !'\\n \\n  $w('#clickMeButton').onClick(() =\u003e {\\n    $w('#helloText').text = 'HELLO WIX !';\\n  });\\n});\\n\"}],\"actionParams\":[{\"name\":\"selector\",\"slug\":\"selector\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"A selector or multiple comma-separated selectors.\"}],\"description\":\"Selects and returns elements from a page.\\r\\n\\r\\nThe `$w()` function selects single or multiple elements by ID or type.\\r\\n\\r\\n To select by ID, pass a selector string with the hash symbol\\r\\n (`#`) followed by the ID of the item you want to select (e.g. `\\\"#myElement\\\"`).\\r\\n The function returns the selected element object.\\r\\n\\r\\n To select by type, pass a selector string with the name of\\r\\n the type without the preceding `#` (e.g. `\\\"Button\\\"`). The function returns\\r\\n an array of the selected element objects. An array is returned even if one\\r\\n or no elements are selected.\\r\\n\\r\\n To select using multiple selectors, pass a selector string with\\r\\n multiple selectors separated by commas. The selectors in the\\r\\n comma-separated string can be ID selectors, type selectors, or a mixture of\\r\\n the two. The function returns an array of the selected element objects.\\r\\n An array is returned even if one or no elements are selected. If two or more\\r\\n selectors select the same element, it's still returned only once in the array.\\r\\n\\r\\n  \u003e **Note:** Most elements accessible for selection by `$w` have basic API properties and functions,\\r\\n like `id`, `type`, `show()`, `hide()`, and others. Use Velo's autocomplete\\r\\n in the code panel to see which API functions and properties are available\\r\\n for each element.\",\"sdkErrors\":[]},{\"name\":\"at\",\"fqn\":\"at\",\"slug\":\"at\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"context\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"$w\",\"referenceFqn\":\"\",\"description\":\"A selector function for the given context.\"},\"examples\":[{\"title\":\"Select an element in a repeated item\",\"description\":\"In this example, we have a repeater where each item contains an image and\\n a text element. When an image is clicked, the value of the text element in\\n the same repeated item is changed to \\\"Selected\\\". All the other text elements\\n in the other repeated items are not affected.\",\"content\":\"$w.onReady( function () {\\n  $w(\\\"#myRepeatedImage\\\").onClick( (event) =\u003e {\\n    let $item = $w.at(event.context);\\n    $item(\\\"#myRepeatedText\\\").text = \\\"Selected\\\";\\n  } );\\n} )\"}],\"actionParams\":[{\"name\":\"context\",\"slug\":\"context\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventContext\",\"referenceFqn\":\"Event.EventContext\"},\"description\":\"An event context.\"}],\"description\":\"Gets a selector function for a specific context.\\r\\n\\r\\nThe `at()` function returns a scoped selector where the scope is based on the\\r\\n context property. Usually, you will use `at()` in a event handler that handles\\r\\n events fired on an element contained in a repeater to get a [selector with\\r\\n repeated item scope]($w.Repeater.html#repeated-item-scope). The returned function\\r\\n selects the elements from the same repeater item where the event was fired.\",\"sdkErrors\":[]},{\"name\":\"onReady\",\"fqn\":\"onReady\",\"slug\":\"on-ready\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"initFunction\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"examples\":[{\"title\":\"Run code in an anonymous function when the page loads\",\"content\":\"$w.onReady( function() {\\n  let pageTitle = $w(\\\"#page1\\\").title;\\n} );\"},{\"title\":\"Wait for a Promise to resolve\",\"description\":\"This example demonstrates the technique of returning a Promise so that the\\n page doesn't load until the Promise resolves. Here, we wait for the query to\\n finish and populate a table before displaying the page to users.\",\"content\":\"import wixData from 'wix-data';\\n\\n$w.onReady(function () {\\n  return wixData.query(\\\"myCollection\\\")\\n    .find()\\n    .then( (results) =\u003e {\\n      $w(\\\"#myTable\\\").rows = results.items;\\n    } );\\n} );\\n\"},{\"title\":\"Where to place code\",\"description\":\"This example demonstrates which code should be placed inside the `onReady()`\\n event handler.\",\"content\":\"// Import statement go at the top of your code, outside of onReady()\\nimport wixWindowFrontend from 'wix-window-frontend';\\n\\n// Initialization statements without $w() don't need to be in onReady()\\nlet hideCount = 0;\\n\\n// Code you want to run when the page loads\\n$w.onReady(function () {\\n  console.log(`Device viewing site is: ${wixWindowFrontend.formFactor}`);\\n\\n  // Initialize an element property\\n  $w(\\\"#myTextElement\\\").text = \\\"Hover over to hide\\\";\\n\\n  // Call a function on an element to set its initial state\\n  $w(\\\"#buttonReset\\\").disable();\\n\\n  // Dynamic event handler to be bound when the page loads\\n  $w(\\\"#myTextElement\\\").onMouseIn( (event) =\u003e {\\n    event.target.hide();\\n    console.log(`Hidden ${++hideCount} times`);\\n    $w(\\\"#buttonReset\\\").enable();\\n  } );\\n} );\\n\\n// Static event handler\\nexport function buttonReset_onClick(event) {\\n\\t$w(\\\"#myTextElement\\\").show();\\n  $w(\\\"#buttonReset\\\").disable();\\n}\\n\"},{\"title\":\"Use the Rendering API to avoid inserting an item twice\",\"description\":\"This example demonstrates how to use the `env` property of the Rendering API to\\n make sure an item is inserted into a collection only once.\",\"content\":\"import wixData from 'wix-data';\\nimport wixWindowFrontend from 'wix-window-frontend';\\n\\nlet toInsert = {\\n  \\\"field1\\\": \\\"Some value\\\",\\n  \\\"field2\\\": \\\"Some other value\\\"\\n};\\n\\n$w.onReady(function () {\\n  if (wixWindowFrontend.rendering.env === \\\"browser\\\") {\\n    return wixData.insert(\\\"myCollection\\\", toInsert)\\n      .then( (item) =\u003e {\\n        $w(\\\"#myText\\\").text = item.title;\\n      } );\\n  }\\n} );\\n\"}],\"actionParams\":[{\"name\":\"initFunction\",\"slug\":\"init-function\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"ReadyHandler\",\"referenceFqn\":\"ReadyHandler\",\"isFunction\":true},\"description\":\"The name of the function to run when the page has finished loading.\"}],\"description\":\"Sets the function that runs when all the page elements have finished loading.\\r\\n\\r\\nUse the `onReady()` function for code you want to run before the user starts\\r\\n interacting with your page.\\r\\n\\r\\n The `onReady()` function in the **masterpage.js** file is called before the\\r\\n `onReady()` function in the code for the page being viewed.\\r\\n\\r\\n The following code *should* be placed inside the `onReady()` event handler:\\r\\n\\r\\n + Initialization of element properties: Example: Setting a text element's initial text value.\\r\\n + Function calls on elements to set their initial state: Example: Disabling a button.\\r\\n + Dynamic event handlers that you want bound when the page loads: Example: Setting an event handler to be called when the pointer enters an element.\\r\\n + For SEO, return all content you want search bots to see. Search bots can see the results of any function that runs in `onReady()` and whose promise is resolved before the `onReady()` promise is resolved. For asynchronous functions, ensure the function's promise resolves first by returning it in `onReady()`. Example: Return data queries in `onReady()` if the queried content is populating page elements.\\r\\n\\r\\n\\r\\n The following code should *not* be placed inside the `onReady()` event handler:\\r\\n\\r\\n + Static event handlers that are wired using the Properties panel in the Editor are not placed inside the `onReady()` event handler.\\r\\n + `return` statements containing synchronous functions, especially if there is no impact on rendering (such as a query) and no need for SEO. Avoiding these `return` statements can improve performance.\\r\\n\\r\\n\\r\\n\\r\\n ### Preventing double \\\"side effects\\\"\\r\\n\\r\\n The `onReady()` event handler may be called twice during the page rendering\\r\\n process, once server-side and once client-side.\\r\\n\\r\\n Because `onReady()` code may be run twice, you need to be aware that if your\\r\\n `onReady()` code causes a side effect, such as inserting an item into a collection,\\r\\n that side effect might happen twice. To avoid a side effect from happening twice,\\r\\n use [`wix-window-frontend.rendering.env`](wix-window-frontend.rendering.html#env) to determine\\r\\n where your code is being executed.\",\"sdkErrors\":[]}],\"webhooks\":[],\"articles\":[{\"content\":\"# Introduction\\nThe `$w` namespace contains all of the UI elements, nodes, and\\n events that make up your site. It also includes the [`$w()`]($w/$w),\\n [`onReady()`]($w.html#onReady), and [`at()`]($w.html#at) functions.\\n\\n The APIs in `$w` can only be used in front-end code.\\n\\n You do not need to import `$w`.\\n\\n \u003e **Notes:**\\n \u003e - Most `$w` elements, nodes, and events are described here under Wix Editor Elements. Some `$w`\\n elements are described in context of their functionality. For example, the [`WixForms`]($w/wix-forms/introduction)\\n element is described under the `wix-crm-frontend` namespace because using the API for the Wix Forms app is most relevant in the\\n context of site contacts and visitors.\\n \u003e - Some `$w` elements change their size dynamically, which can [affect the page layout](https://dev.wix.com/docs/develop-websites/articles/wix-editor-elements/formatting-layout/how-page-layout-is-affected-when-elements-change-size).\\n\\n Get hands-on experience with the `$w` API on our [Hello World](https://www.wix.com/velo/example/hello-world) example page.\",\"displayName\":\"Introduction\",\"slugifyName\":\"introduction\"},{\"content\":\"\u003c!-- This article was published using the Doc Push single-sourcing tool. Any changes to this article MUST be made in the source file. Find it at www.github.com/wix-private/velo-docs.--\u003e\\n\\n# Styling Elements with CSS\\n\\n\u003e **Note:** This feature is only available to Wix Studio users.\\n\\n\u003c!-- Outline:\\n\\n- about the feature\\n- how to use it (UI)\\n  - in the styling panel\\n  - in the code panel\\n- brief explanation of constructing semantic class names\\n- ~~list of supported elements~~\\n- ~~see MDN for full CSS documentation~~ --\u003e\\n\\nCSS allows you to customize the appearance of your website, from colors and fonts to sizes and positions \\nof different elements. For additional information on CSS styling options, refer to the \\n[MDN CSS reference docs](https://developer.mozilla.org/en-US/docs/Learn/CSS).\\n\\n## Add CSS to your site\\n\\nTo get started, \u003cstrong\u003eadd a global.css\u003c/strong\u003e file in the \u003cstrong\u003eCSS\u003c/strong\u003e section of your Page Code. \\nCSS styles added to this file will apply to the selected classes throughout your site. \\nTo select a class to style, use the name of the component as it's referred to in Velo. \\n\\nFor example, to change the background color of all buttons to red:\\n```css\\n.button {\\n  background-color: red;\\n}\\n```\\n\\nUse inner classes to style specific elements of a component class. \\nFor example, use `.button__label` to style only the labels of button elements.\\n\\n## Available classes\\n\\nSee which classes are already available for any element on your site by selecting the element and \\nviewing \u003cstrong\u003eCSS Classes\u003c/strong\u003e in your code panel:\\n\\n![CSS Classes in code panel](https://wixmp-833713b177cebf373f611808.wixmp.com/images/velo-images/media_css_classes_code_panel.png \\\"CSS Classes in code panel\\\")\\n\\nOr add your own classes in the custom classes field.\\n\\nFor reference, here is a list of global classes:\\n- [Accordion]($w/accordion/css-classes)\\n- [Anchor menu]($w/menu/css-classes#anchor-menu)\\n- [Audio player](/audio-player/css-classes)\\n- [Box]($w/box/css-classes)\\n- [Breadcrumbs]($w/breadcrumbs/css-classes)\\n- [Button]($w/button/css-classes)\\n- [Captcha]($w/captcha/css-classes)\\n- [Checkbox]($w/checkbox/css-classes)\\n- [Checkbox group](/checkbox-group/css-classes)\\n- [Collapsible text](/collapsible-text/css-classes)\\n- [Column strip](/column-strip/css-classes)\\n- [Date picker](/date-picker/css-classes)\\n- [Dropdown input]($w/dropdown/css-classes)\\n- [Dropdown menu]($w/menu/css-classes#dropdown-menu)\\n- [Footer]($w/footer/css-classes)\\n- [Form]($w/form/css-classes)\\n- [Google map](/google-map/css-classes)\\n- [Header]($w/header/css-classes)\\n- [Horizontal line](#horizontal-line)\\n- [Horizontal menu]($w/menu/css-classes#horizontal-menu)\\n- [Image]($w/image/css-classes)\\n- [Image button](#image-button-classes)\\n- [Language menu](#language-menu-classes)\\n- [Lightbox](#lightbox-classes)\\n- [Lottie]($w/lottie/css-classes)\\n- [Menu]($w/menu/css-classes)\\n- [Menu container](/menu-container/css-classes)\\n- [Multi-state box](/multi-state-box/css-classes)\\n- [Page]($w/page/css-classes)\\n- [Pagination]($w/pagination/css-classes)\\n- [Progress bar](/progress-bar/css-classes)\\n- [Radio button group](/radio-button-group/css-classes)\\n- [Ratings display](/ratings-display/css-classes)\\n- [Ratings input](/ratings-input/css-classes)\\n- [Repeater]($w/repeater/css-classes)\\n- [Rich text box](/rich-text-box/css-classes)\\n- [Search bar](#search-bar-classes)\\n- [Section](https://dev.wix.com/docs/velo/api-reference/$w/section/css-classes)\\n- [Selection tags](/selection-tags/css-classes)\\n- [Signature input](/signature-input/css-classes)\\n- [Slideshow]($w/slideshow/css-classes)\\n- [Switch]($w/switch/css-classes)\\n- [Table]($w/table/css-classes)\\n- [Tabs]($w/tabs/css-classes)\\n- [Text]($w/text/css-classes)\\n- [Text box](/text-box/css-classes)\\n- [Text input](/text-input/css-classes)\\n- [Time picker](/time-picker/css-classes)\\n- [Upload button](/upload-button/css-classes)\\n- [Vector image](/vector-image/css-classes)\\n- [Vertical line](#vertical-line)\\n- [Vertical menu]($w/menu/css-classes#vertical-menu)\\n- [Video box](/video-box/css-classes)\\n- [Video player](/video-player/css-classes)\\n\\nThe following classes can be customized but don't have an associated $w API:\\n\\n### Image button classes\\n\\n#### `.image-button`\\n\\nTargets image button elements.\\nFor example:\\n\\n```css\\n.image-button {\\n  background-color: #e6e6e6;\\n  padding: 10px;\\n  border-radius: 10px;\\n}\\n```\\n\\n### Language menu classes\\n\\n#### `.language-menu`\\n\\nTargets language menu elements.\\nFor example:\\n\\n```css\\n.language-menu {\\n  background-color: #e6e6e6;\\n  padding: 10px;\\n  border-radius: 10px;\\n}\\n```\\n\\n#### `.language-menu__option`\\n\\nTargets language menu option elements.\\nFor example:\\n\\n```css\\n.language-menu__option {\\n  background-color: #dfd2f4;\\n  font-family: monospace;\\n}\\n```\\n\\n### Lightbox classes\\n\\n#### `.lightbox`\\n\\nTargets lightbox elements.\\nFor example:\\n\\n```css\\n.lightbox {\\n  border: 5px solid #d1a917;\\n  border-radius: 6px;\\n  filter: drop-shadow(2px 4px 6px black);\\n}\\n```\\n\\n#### `.lightbox__close-button`\\n\\nTargets lightbox close buttons.\\nFor example:\\n\\n```css\\n.lightbox__close-button {\\n  width: 10px;\\n}\\n```\\n\\n### Line classes\\n\\n#### `.horizontal-line`\\n\\nTargets horizontal line elements.\\nFor example:\\n\\n```css\\n.horizontal-line {\\n  border-top: 6px dotted orange;\\n}\\n```\\n\\n#### `.vertical-line`\\n\\nTargets vertical line elements.\\nFor example:\\n\\n```css\\n.vertical-line {\\n  border-left: 12px dashed pink;\\n}\\n```\\n\\n### Search bar classes\\n\\n#### `.search-bar`\\n\\nTargets search bar elements.\\nFor example:\\n\\n```css\\n.search-bar {\\n  width: 500px;\\n  display: flex;\\n  flex-direction: row;\\n}\\n```\\n\\n#### `.search-bar__icon`\\n\\nTargets search bar icons.\\nFor example:\\n\\n```css\\n.search-bar__icon {\\n  fill: #840292;\\n}\\n```\\n\\n#### `.search-bar__input`\\n\\nTargets search bar input boxes.\\nFor example:\\n\\n```css\\n.search-bar__input {\\n  border: none;\\n  border-bottom: 2px solid #840292;\\n  background-color: #dfd2f4;\\n  font-family: monospace;\\n}\\n```\\n\",\"displayName\":\"Styling Elements with CSS\",\"slugifyName\":\"styling-elements-with-css\"}],\"namespaces\":[{\"name\":\"Accordion\",\"slug\":\"accordion\",\"fqn\":\"Accordion\",\"standaloneTypes\":[],\"metadata\":{},\"actions\":[{\"name\":\"delete\",\"fqn\":\"Element.delete\",\"slug\":\"delete\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When the element's `deleted` property has been set to `true`.\"},\"examples\":[{\"title\":\"Delete an element from the DOM\",\"content\":\"$w(\\\"#myElement\\\").delete();\"},{\"title\":\"Delete an element from the DOM and log a message when done\",\"content\":\"$w(\\\"#myElement\\\").delete()\\n  .then( () =\u003e {\\n    console.log(\\\"Done with delete\\\");\\n  } );\"}],\"description\":\"Deletes an element from the [DOM](https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction). \\r\\nThis is a temporary deletion. Use [`restore`](#restore) to restore the deleted element.  \\r\\n\\r\\nSEO crawlers cannot find content in an element whose `deleted` status is `true`. \\r\\nContent in an element that is in `hidden` status can be found by crawlers.\\r\\n\\r\\n\u003e**Note:** An element whose `deleted` status is `true` can be edited.\\r\\n\\r\\nThe `delete()` function returns a Promise that is resolved when the\\r\\n element's `deleted` property has been set to `true`.\",\"sdkErrors\":[]},{\"name\":\"onMouseIn\",\"fqn\":\"Element.onMouseIn\",\"slug\":\"on-mouse-in\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\",\"description\":\"The element to which the event handler was added.\"},\"examples\":[{\"title\":\"Get the mouse event info when the mouse enters an element\",\"content\":\"$w(\\\"#myElement\\\").onMouseIn( (event) =\u003e {\\n  let clientX = event.clientX;  // 362\\n  let clientY = event.clientY;  // 244\\n  let offsetX = event.offsetX;  // 10\\n  let offsetY = event.offsetY;  // 12\\n  let pageX = event.pageX;      // 362\\n  let pageY = event.pageY;      // 376\\n  let screenX = event.screenX;  // 3897\\n  let screenY = event.screenY;  // 362\\n} );\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"MouseEventHandler\",\"referenceFqn\":\"MouseEventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the pointer is moved onto the\\r\\n element.\"}],\"description\":\"Adds an event handler that runs when the pointer is moved\\r\\n onto the element.\",\"sdkErrors\":[]},{\"name\":\"onMouseOut\",\"fqn\":\"Element.onMouseOut\",\"slug\":\"on-mouse-out\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\",\"description\":\"The element to which the event handler was added.\"},\"examples\":[{\"title\":\"Get the mouse event info when the mouse exits an element\",\"content\":\"$w(\\\"#myElement\\\").onMouseOut( (event) =\u003e {\\n  let clientX = event.clientX;  // 362\\n  let clientY = event.clientY;  // 244\\n  let offsetX = event.offsetX;  // 10\\n  let offsetY = event.offsetY;  // 12\\n  let pageX = event.pageX;      // 362\\n  let pageY = event.pageY;      // 376\\n  let screenX = event.screenX;  // 3897\\n  let screenY = event.screenY;  // 362\\n} );\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"MouseEventHandler\",\"referenceFqn\":\"MouseEventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the pointer is moved off of\\r\\n the element.\"}],\"description\":\"Adds an event handler that runs when the pointer is moved\\r\\n off of the element.\",\"sdkErrors\":[]},{\"name\":\"onViewportEnter\",\"fqn\":\"ViewportMixin.onViewportEnter\",\"slug\":\"on-viewport-enter\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\",\"description\":\"The element on which the event is now registered.\"},\"examples\":[{\"title\":\"Get the ID of the element that has entered the viewport\",\"content\":\"$w(\\\"#myElement\\\").onViewportEnter( (event) =\u003e {\\n  let targetId = event.target.id; // \\\"myElement\\\"\\n});\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventHandler\",\"referenceFqn\":\"EventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the element enters the viewport.\"}],\"description\":\"Adds an event handler that runs when an element is displayed\\r\\n in the viewable part of the current window.\\r\\n\\r\\nAn element enters the viewport when the page is scrolled to show any\\r\\n part of the element. An element also enters the viewport if it was\\r\\n `hidden` or `collapsed`\\r\\n and is then shown or expanded in the viewable part of the current window. `onViewportEnter()` \\r\\n is not fired for `hidden` or `collapsed` \\r\\n elements even if they are scrolled into view.\",\"sdkErrors\":[]},{\"name\":\"onViewportLeave\",\"fqn\":\"ViewportMixin.onViewportLeave\",\"slug\":\"on-viewport-leave\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\",\"description\":\"The element on which the event is now registered.\"},\"examples\":[{\"title\":\"Get the ID of the element that has left the viewport\",\"content\":\"$w(\\\"#myElement\\\").onViewportLeave( (event) =\u003e {\\n  let targetId = event.target.id; // \\\"myElement\\\"\\n});\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventHandler\",\"referenceFqn\":\"EventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the element leaves the viewport.\"}],\"description\":\"Adds an event handler that runs when an element is no longer\\r\\n displayed in the viewable part of the current window.\\r\\n\\r\\nAn element leaves the viewport when the page is scrolled so that the\\r\\n element is completely out of view. An element also leaves the viewport\\r\\n if it was shown or expanded and is then `hidden`\\r\\n or `collapsed` from the viewable part\\r\\n of the current window.  `onViewportLeave()` \\r\\n is not fired for `hidden` or `collapsed` \\r\\n elements even if they are scrolled out of view.\",\"sdkErrors\":[]},{\"name\":\"restore\",\"fqn\":\"Element.restore\",\"slug\":\"restore\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When the element's `deleted` property has been set to `false`.\"},\"examples\":[{\"title\":\"Restore a deleted element to the DOM\",\"content\":\"$w(\\\"#myElement\\\").restore();\"},{\"title\":\"Restore an element to the DOM and log a message when done\",\"content\":\"$w(\\\"#myElement\\\").restore()\\n  .then( () =\u003e {\\n    console.log(\\\"Done with restore\\\");\\n  } );\"}],\"description\":\"Restores a deleted element to the [DOM](https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction).\\r\\n\\r\\nThe `restore()` function returns a Promise that is resolved when the\\r\\n element's `deleted` property has been set to `false`.\\r\\n See the [`delete`](#delete) function.\",\"sdkErrors\":[]},{\"name\":\"scrollTo\",\"fqn\":\"Node.scrollTo\",\"slug\":\"scroll-to\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When the scroll is complete.\"},\"examples\":[{\"title\":\"Scroll the page to an element\",\"content\":\"$w(\\\"#myElement\\\").scrollTo();\"},{\"title\":\"Scroll the page to an element and log a message when done\",\"content\":\"$w(\\\"#myElement\\\").scrollTo()\\n  .then( ( ) =\u003e {\\n    console.log(\\\"Done with scroll\\\");\\n} );\"}],\"description\":\"Scrolls the page to the top of the element using an animation.\\r\\n\\r\\nThe `scrollTo()` function returns a Promise that is resolved when the\\r\\n animated scroll is complete and the element is in view.\\r\\n\\r\\n To scroll to a specific location on the page, see the `wix-window-frontend`\\r\\n [`scrollTo()`](wix-window-frontend.html#scrollTo) function. \\r\\n\\r\\n \u003e **Tip**: Use the `wix-window-frontend` [`scrollTo()`](wix-window-frontend.html#scrollTo) function to \\r\\n scroll directly to an element, and also disable the animation. \\r\\n To get the coordinates for scrolling, display the Wix Editor Toolbar. In the Editor, \\r\\n move the cursor to the top-left pixel where you want the page to scroll to. The **X** \\r\\n and **Y** axis **Position** values show the coordinates.\\r\\n \\r\\n \\r\\n\\r\\n \u003e **Note:** \\r\\n \u003e To use `scrollTo()` with a header element, the [Header Scroll Setting](https://support.wix.com/en/article/wix-editor-changing-the-header-scroll-settings) must be set to **Scrolls with site**. To scroll to the header with other settings, use the `wix-window-frontend` [`scrollTo()`](wix-window-frontend.html#scrollTo) function.\",\"sdkErrors\":[]}],\"webhooks\":[],\"articles\":[{\"content\":\"# Introduction\\n\u003e This feature is currently only available in Wix Studio.\\n\\nAn accordion element holds multiple, collapsible item elements in a vertical stack,\\neach with different content.\\nAccordions can be configured so that only one item is expanded at a time,\\nor so that multiple containers can be expanded simultaneously.\\nSite visitors can click an accordion item's title to expand or collapse the item.\\n\\n![Example of an accordion element rendered on a webpage, with one expanded item and three collapsed items](https://wixmp-833713b177cebf373f611808.wixmp.com/images/velo-images/media_accordion.png).\\n\\n\\nWith Velo, you can scroll to an accordion and modify accordion styles.\",\"displayName\":\"Introduction\",\"slugifyName\":\"introduction\"},{\"content\":\"\u003c!-- This article was published using the Doc Push single-sourcing tool. Any changes to this article MUST be made in the source file. Find it at www.github.com/wix-private/velo-docs.--\u003e\\n\\n# Accordion CSS Classes\\n\\n\u003e **Note:** This feature is only available to Wix Studio users.\\n\\nYou can use the classes listed below\\nto style your `Accordion` elements with CSS.\\n\\nFor more information on styling your elements with CSS, see\\n[Styling Elements with CSS]($w/styling-elements-with-css) and the\\n[MDN CSS reference docs](https://developer.mozilla.org/en-US/docs/Learn/CSS).\\n\\n\u003cblockquote class=\\\"important\\\"\u003e\\n\\n__Important:__\\nElement structure and undocumented class names\\nmay change without advance warning.\\nTo avoid unintended style changes to your site,\\nselect elements with the documented class names only.\\n\\n\u003c/blockquote\u003e\\n\\n## `.accordion`\\n\\nTargets accordion elements.\\nFor example:\\n\\n```css\\n.accordion {\\n  opacity: 75%;\\n  display: flex;\\n}\\n```\\n\\n## `.accordion__title`\\n\\nTargets accordion title elements.\\nFor example:\\n\\n```css\\n.accordion__title {\\n  text-transform: uppercase;\\n  font-weight: 700;\\n}\\n```\\n\\n## `.accordion__container`\\n\\nTargets accordion container elements.\\nFor example:\\n\\n```css\\n.accordion__container {\\n  background-color: #a2a2fc;\\n}\\n```\\n\\n## `.accordion__item`\\n\\nTargets accordion item elements.\\nFor example:\\n\\n```css\\n.accordion__item {\\n  padding: 5px;\\n  border-top-left-radius: 12px;\\n  border-bottom-left-radius: 12px;\\n}\\n```\\n\\n## `.accordion__icon`\\n\\nTargets accordion icon elements.\\nFor example:\\n\\n```css\\n.accordion__icon {\\n  fill: #FF0000;\\n}\\n```\\n\",\"displayName\":\"CSS Classes\",\"slugifyName\":\"css-classes\"}],\"builderTypes\":[],\"properties\":[{\"name\":\"customClassList\",\"slug\":\"custom-class-list\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Gets a list of the classes of an element\",\"content\":\"$w(\\\"#myElement\\\").customClassList.values(); // [\\\"className1\\\", \\\"className2\\\"]\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"CustomClassList\",\"referenceFqn\":\"CustomClassList.CustomClassList\"},\"description\":\"A property that represents an element's custom CSS classes.\\r\\n\\r\\n\u003e This property is not yet available to all users.\\r\\n\\r\\nYou can use this property to manipulate the custom CSS classes of an element. For example, \\r\\nyou can add a custom class to an element or replace an existing class with a new custom class.\\r\\n\\r\\n\\r\\nCustom classes are those that you create on your site, not the predefined global classes\\r\\nthat are provided for each element.  \\r\\n\\r\\n\u003e **Note:** For more information, see [Styling Elements with CSS](https://www.wix.com/velo/reference/$w/styling-elements-with-css) \\r\\n\u003e and the [MDN CSS reference docs](https://developer.mozilla.org/en-US/docs/Learn/CSS).\"},{\"name\":\"deleted\",\"slug\":\"deleted\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get an element's deleted status\",\"content\":\"const isDeleted = $w(\\\"#myElement\\\").deleted;  // true\"},{\"title\":\"Toggle an element's deleted state\",\"content\":\"if( $w(\\\"#myElement\\\").deleted ) {\\n  $w(\\\"#myElement\\\").restore();\\n}\\nelse {\\n  $w(\\\"#myElement\\\").delete();\\n}\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if an element was temporarily deleted from the [DOM](https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction).\\r\\nUse the [`restore`](#restore) function to restore the deleted element.\\r\\n\\r\\nIf `deleted` is `true`, the element is not in the current DOM.\\r\\n\\r\\n If `deleted` is `false` the element is in the current DOM.\\r\\n\\r\\n\u003e**Notes:**\\r\\n\u003e - An element whose `deleted` status is `true` can be edited.\\r\\n\u003e - In Wix Studio, an element whose `deleted` status is `false` will not be displayed if the element has been set to **Hide**.\"},{\"name\":\"global\",\"slug\":\"global\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get whether an element is displayed on all pages\",\"content\":\"let isGlobal = $w(\\\"#myElement\\\").global; // false\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if an element appears on all pages or only on the current page.\\r\\n\\r\\nIf `global` is `true`, the element appears on all pages.\\r\\n\\r\\n If `global` is `false`, the element only appears on the current page.\"},{\"name\":\"id\",\"slug\":\"id\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the ID\",\"content\":\"let myId = $w(\\\"#myElement\\\").id; // \\\"myElement\\\"\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the element's ID.\\r\\n\\r\\nThe ID is the element's unique identifier. It is used when selecting\\r\\n elements using the [`$w()`]($w.html#$w) function.\\r\\n\\r\\n An element's `id` is set in the Editor using the [Properties panel](https://support.wix.com/en/article/how-do-i-use-the-properties-panel).\"},{\"name\":\"parent\",\"slug\":\"parent\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the parent element and the parent's ID\",\"content\":\"let parentElement = $w(\\\"#myElement\\\").parent;\\n\\nlet parentId = parentElement.id; // \\\"page1\\\"\"}],\"type\":{\"kind\":\"REFERENCE\",\"name\":\"Node\",\"referenceFqn\":\"Node.Node\"},\"description\":\"Gets the element's parent element.\\r\\n\\r\\nSome elements can contain other elements. This occurs when you drag\\r\\n an element onto a container element. The container is the `parent` of\\r\\n all the elements it contains.\\r\\n\\r\\n [`Page`]($w.Page.html), [`Header`]($w.Header.html), and\\r\\n [`Footer`]($w.Footer.html) are top-level elements and have no parent.\"},{\"name\":\"rendered\",\"slug\":\"rendered\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get an element's rendered status\",\"content\":\"let isRendered = $w(\\\"#myElement\\\").rendered;  // true\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if an element is currently in the [DOM structure](https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction).\\r\\n\\r\\nIf `rendered` is `true`, the element is in the current DOM structure and\\r\\n can be used.\\r\\n\\r\\n If `rendered` is `false` the element is not in the current DOM structure.\\r\\n\\r\\n An element might not be in the DOM if it is in a [slide]($w.Slide.html) or a [state]($w.State.html)\\r\\n which is not currently showing.\"},{\"name\":\"type\",\"slug\":\"type\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the element's type\",\"content\":\"let myType = $w(\\\"#myElement\\\").type; // \\\"$w.Type\\\"\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the element's type.\\r\\n\\r\\nPossible values include:\\r\\n\\r\\n - `$w.TextInput`\\r\\n - `$w.TextBox`\\r\\n - `$w.RichTextBox`\\r\\n - `$w.RadioButtonGroup`\\r\\n - `$w.CheckboxGroup`\\r\\n - `$w.Dropdown`\\r\\n - `$w.SelectionTags`\\r\\n - `$w.Slider`\\r\\n - `$w.DatePicker`\\r\\n - `$w.UploadButton`\\r\\n - `$w.RatingsInput`\\r\\n - `$w.AddressInput`\\r\\n - `$w.Switch`\\r\\n - `$w.SignatureInput`\\r\\n - `$w.Captcha`\"}]},{\"name\":\"AccountNavBar\",\"slug\":\"account-nav-bar\",\"fqn\":\"AccountNavBar\",\"standaloneTypes\":[],\"metadata\":{},\"actions\":[{\"name\":\"delete\",\"fqn\":\"Element.delete\",\"slug\":\"delete\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When the element's `deleted` property has been set to `true`.\"},\"examples\":[{\"title\":\"Delete an element from the DOM\",\"content\":\"$w(\\\"#myElement\\\").delete();\"},{\"title\":\"Delete an element from the DOM and log a message when done\",\"content\":