ains information about the message that was sent.\",\"sdkErrors\":[]},{\"name\":\"onMinimize\",\"fqn\":\"Chatbox.onMinimize\",\"slug\":\"on-minimize\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"examples\":[{\"title\":\"Register a callback to run after the chatbox is minimized\",\"content\":\"$w(\\\"#myChatbox\\\").onMinimize(() =\u003e {\\n  console.log(\\\"Chatbox minimized\\\");\\n});\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"BasicEventHandler\",\"referenceFqn\":\"BasicEventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the chatbox is minimized.\"}],\"description\":\"An event that fires when the chatbox is minimized.\",\"sdkErrors\":[]},{\"name\":\"onViewportEnter\",\"fqn\":\"Chatbox.onViewportEnter\",\"slug\":\"on-viewport-enter\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\",\"description\":\"The element on which the event is now registered.\"},\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventHandler\",\"referenceFqn\":\"EventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the element enters the viewport.\"}],\"description\":\"Note: This standard element event is not relevant for Chatbox.\\r\\n\\r\\nAdds an event handler that runs when an element is displayed\\r\\n i