target.value;  // \\\"new value\\\"\\n});\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"EventHandler\",\"referenceFqn\":\"EventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when the element's value changes.\"}],\"description\":\"Adds an event handler that runs when an input element's value\\r\\n is changed.\\r\\n\\r\\nAn element receives a `change` event when a user changes the value\\r\\n in an input element.\\r\\n\\r\\n A `change` event is not triggered when you change an element's value using\\r\\n the element's [`value`](#value) property.\\r\\n\\r\\n Because `onChange()` is fired before validations are performed, do not check \\r\\n any of the validation properties in the `onChange()` event handler. For example, \\r\\n do not code an if statement that checks the `valid` property in the `onChange()` \\r\\n because the property at this point contains values prior to the `onChange()`.\",\"sdkErrors\":[]},{\"name\":\"disable\",\"fqn\":\"DisabledMixin.disable\",\"slug\":\"disable\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When the element's `enabled` property has been set to `false`.\"},\"examples\":[{\"title\":\"Disable an element\",\"content\":\"$w(\\\"#myElement\\\").disable();\"},{\"title\":\"Disable an element and log a message when done\",\"content\":\"$w(\\\"#myElement\\\").disable()\\n  .then( () =\u003e {\\n    console.log(\\\"Element now disabled\\\");\\n  } );\"},{\"title\":\"Toggle an element's enabled state\",\"content\":\"if( $w(\\\"#myElement\\\").enabled ) {\\n  $w(\\\"#myElement\\\").disable();\\n}\\nelse {\\n  $w(\\\"#myElement\\\").enable();\\n}\"}],\"description\":\"Disables the element and sets its `enabled` property to `false`.\\r\\n\\r\\nThe `disable()` function returns a Promise that is resolved when the\\r\\n element's [`enabled`](#enabled) property has been set to `false`.\\r\\n\\r\\n To learn about the behavior of a disabled element,\\r\\n see the [`enabled`](#enabled) property.\",\"sdkErrors\":[]},{\"name\":\"enable\",\"fqn\":\"DisabledMixin.enable\",\"slug\":\"enable\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When the element's `enabled` property has been set to `true`.\"},\"examples\":[{\"title\":\"Enable an element\",\"content\":\"$w(\\\"#myElement\\\").enable();\"},{\"title\":\"Enable an element and log a message when done\",\"content\":\"$w(\\\"#myElement\\\").enable()\\n  .then( () =\u003e {\\n    console.log(\\\"Element now enabled\\\");\\n  } );\"},{\"title\":\"Toggle an element's enabled state\",\"content\":\"if( $w(\\\"#myElement\\\").enabled ) {\\n  $w(\\\"#myElement\\\").disable();\\n}\\nelse {\\n  $w(\\\"#myElement\\\").enable();\\n}\"}],\"description\":\"Enables the element and sets its `enabled` property to `true`.\\r\\n\\r\\nThe `enable()` function returns a Promise that is resolved when the\\r\\n element's [`enabled`](#enabled) property has been set to `true`.\\r\\n\\r\\n To learn about the behavior of an enabled element,\\r\\n see the [`enabled`](#enabled) property.\",\"sdkErrors\":[]}],\"webhooks\":[],\"articles\":[{\"content\":\"# Introduction\\nInput elements provide a way for site visitors to enter text on your site page. \\n\\nThe dashboard input element is intended for use on \\n[dashboard pages](https://dev.wix.com/docs/develop-websites/articles/coding-with-velo/frontend-code/dashboard-admin-pages/working-with-dashboard-pages) \\nin your Wix site or in [Wix Blocks](https://support.wix.com/en/article/wix-blocks-check-out-our-articles),\\nbut you may use it on any page.\",\"displayName\":\"Introduction\",\"slugifyName\":\"introduction\"}],\"builderTypes\":[],\"properties\":[{\"name\":\"customClassList\",\"slug\":\"custom-class-list\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"CustomClassList\",\"referenceFqn\":\"CustomClassList.CustomClassList\"},\"description\":\"Note: This standard element property is not relevant for this DashboardInput.\\r\\n\\r\\n\u003e This property is not yet available to all users.\\r\\n\\r\\nYou can use this property to manipulate the custom CSS classes of an element. For example, \\r\\nyou can add a custom class to an element or replace an existing class with a new custom class.\\r\\n\\r\\n\\r\\nCustom classes are those that you create on your site, not the predefined global classes\\r\\nthat are provided for each element.  \\r\\n\\r\\n\u003e **Note:** For more information, see [Styling Elements with CSS](https://www.wix.com/velo/reference/$w/styling-elements-with-css) \\r\\n\u003e and the [MDN CSS reference docs](https://developer.mozilla.org/en-US/docs/Learn/CSS).\"},{\"name\":\"label\",\"slug\":\"label\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the dashboard input's label\",\"content\":\"let myLabel = $w('#myElement').label;  // \\\"Full Name\\\"\"},{\"title\":\"Set the dashboard input's label\",\"content\":\"$w('#myElement').label = \\\"Full Name\\\";\"},{\"title\":\"Disable the dashboard input's label\",\"content\":\"$w('#myElement').label = null; // Disables the element's label\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Sets or gets the dashboard input's label.\\r\\n\\r\\nMax: 120 characters\"},{\"name\":\"placeholder\",\"slug\":\"placeholder\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the dashboard input's placeholder\",\"content\":\"let myPlaceholder = $w('#myElement').placeholder;  // \\\"Email\\\"\"},{\"title\":\"Set the dashboard input's placeholder\",\"content\":\"$w('#myElement').placeholder = \\\"Email\\\";\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Sets or gets the placeholder text content.\\r\\n\\r\\nPlaceholder text is typically used to provide a hint to the user of what to enter into an input element that accepts text.\\r\\nWhen the user begins to enter text, the placeholder text disappears. Set `placeholder` to `null` to disable.\\r\\n\\r\\nMax: 1200 characters\"},{\"name\":\"prefix\",\"slug\":\"prefix\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the dashboard input prefix\",\"content\":\"let prefix = $w('#myInput').prefix; // $\"},{\"title\":\"Set the dashboard input prefix to a string literal\",\"content\":\"$w('#myInput').prefix = \\\"$\\\";\"},{\"title\":\"Set the dashboard input prefix to a vector image in the Media Manager\",\"content\":\"$w('#myElement').prefix = 'wix:vector://v1/ce0334_2cec984ab68c490891dda1b53a33fead.svg/my-vector-graphic.svg';\"},{\"title\":\"Set the dashboard input prefix to a vector XML string\",\"content\":\"$w('#myElement').prefix = '\u003csvg height=\\\"10\\\" width=\\\"10\\\"\u003e\u003cpolygon points=\\\"0,9 9,9 5,0\\\" style=\\\"fill:lime;stroke:purple;stroke-width:1\\\"/\u003e\u003c/svg\u003e';\"},{\"title\":\"Disable the dashboard input prefix\",\"content\":\"$w('#myElement').prefix = null; // Disable the button's prefix property\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Sets or gets the dashboard input prefix.\\r\\n\\r\\nYou can get or set a prefix for a dashboard input element. For example, you can set a prefix to be a currency, such as `'$'`.\\r\\n\\r\\nThe following formats are supported:\\r\\n\\r\\n+ A string literal, such as `'$'`\\r\\n+ Vector images from the Media Manager: `wix:vector://v1//`\\r\\n+ Vector images from the web: `http(s)://`\\r\\n+ Vector XML strings: `...`\\r\\n\\r\\nTo disable the dashboard input prefix, set the `prefix` property to `null`.\"},{\"name\":\"readOnly\",\"slug\":\"read-only\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Check if a dashboard input is read-only\",\"content\":\"let isReadOnly = $w('#myElement').readOnly; // true\"},{\"title\":\"Set a dashboard input to be read-only\",\"content\":\"$w('#myElement').readOnly = true;\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if the dashboard input element is read-only.\\r\\n\\r\\nBy default, `readOnly` is set to `false`. This allows site visitors to edit the field.\\r\\n\\r\\nIf `readOnly` is set to `true`, then the input field appears greyed out on your site and visitors cannot modify it.\"},{\"name\":\"suffix\",\"slug\":\"suffix\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the dashboard input suffix\",\"content\":\"let prefix = $w('#myInput').suffix; // %\"},{\"title\":\"Set the dashboard input suffix to a string literal\",\"content\":\"$w('#myInput').suffix = '%';\"},{\"title\":\"Set the dashboard input suffix to an vector image in the Media Manager\",\"content\":\"$w('#myElement').suffix = 'wix:vector://v1/ce0334_2cec984ab68c490891dda1b53a33fead.svg/my-vector-graphic.svg';\"},{\"title\":\"Set the dashboard input suffix to a vector XML string\",\"content\":\"$w('#myElement').suffix = '\u003csvg height=\\\"10\\\" width=\\\"10\\\"\u003e\u003cpolygon points=\\\"0,9 9,9 5,0\\\" style=\\\"fill:lime;stroke:purple;stroke-width:1\\\"/\u003e\u003c/svg\u003e';\"},{\"title\":\"Disable the dashboard input suffix\",\"content\":\"$w('#myElement').suffix = null; // Disable the button's suffix property\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Sets or gets the dashboard input suffix.\\r\\n\\r\\nYou can set or get a suffix for a dashboard input element. For example, you can set a suffix to be a unit of measurement, such as `'cm'`.\\r\\n\\r\\nThe following formats are supported:\\r\\n\\r\\n+ A string literal, such as `'cm'`\\r\\n+ Vector images from the Media Manager: `wix:vector://v1//`\\r\\n+ Vector images from the web: `http(s)://`\\r\\n+ Vector XML strings: `...`\\r\\n\\r\\nTo disable the dashboard input suffix, set the `suffix` property to `null`.\"},{\"name\":\"tooltip\",\"slug\":\"tooltip\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the dashboard input's tooltip\",\"content\":\"let tooltip = $w('#myElement').tooltip; // \\\"Submit your information here\\\"\"},{\"title\":\"Set the dashboard input's tooltip\",\"content\":\"$w('#myElement').tooltip = \\\"Submit your information here\\\";\"},{\"title\":\"Disable the dashboard input's tooltip\",\"content\":\"$w('#myElement').tooltip = null; // Disables the tooltip\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Sets or gets the dashboard input element's tooltip content.\\r\\n\\r\\nSetting the `tooltip` property defines the text that is displayed when a visitor hovers over an element's ![tooltip-icon](https://wixmp-833713b177cebf373f611808.wixmp.com/images/velo-images/media_tooltip-icon.png) icon.\\r\\nSet `tooltip` to `null` to disable.\\r\\n\\r\\nMax: 1200 characters\"},{\"name\":\"value\",\"slug\":\"value\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get the dashboard input field's value\",\"content\":\"let myValue = $w('#myInput').value; // \\\"10 Main Street\\\"\"},{\"title\":\"Set the dashboard input field's value\",\"content\":\"$w('#myInput').value = \\\"10 Main Street\\\";\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Sets or gets the value in the dashboard input field.\\r\\n\\r\\nTo reset the text input and restore any placeholder text, set the value property to `null` or `undefined`.\\r\\n\\r\\n\u003e **Note:**\\r\\n\u003e + Changing a text input's `value` in code does not trigger an `onChange` event.\"},{\"name\":\"collapsed\",\"slug\":\"collapsed\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if the element is collapsed or expanded.\\r\\n\\r\\nIf `collapsed` is `true`, the element is not displayed on the page under\\r\\n any circumstances. However, the collapsed element is still in the site's DOM. Unlike a\\r\\n `hidden` element, a collapsed element doesn't take up any\\r\\n space on the page. When collapsed, elements positioned within 70 pixels\\r\\n below the collapsed element and each other move up to take the\\r\\n collapsed element's place where possible. The elements that move up\\r\\n maintain their positions relative to one another.\\r\\n\\r\\n If `collapsed` is `false`, the element _may_ be displayed on the page.\\r\\n Elements that moved up to take the collapsed element's place on the\\r\\n page are moved back down.\\r\\n\\r\\n However, an expanded element (an element whose `collapsed` property is\\r\\n `false`) is still not displayed if:\\r\\n\\r\\n + It is `hidden`.\\r\\n + Its parent element is hidden or collapsed.\\r\\n + It is a slide in a [Slideshow]($w.Slideshow.html) which is\\r\\n   currently not being displayed.\\r\\n + In Wix Studio, it has been set to **Hide** in the [Layers panel](https://wix.wixanswers.com/apps/widget/v1/wix/53f85d67-f8b0-41ca-9dc8-5a16390cc74f/view/en/article/9b13ee7a-06b1-4fde-80e7-8f978d9d3195#:~:text=a%20specific%20breakpoint%3F-,Yes,-.%C2%A0You%20can%20hide) in that breakpoint. \\r\\n\\r\\n\\r\\n Even if the element is not displayed due to the conditions\\r\\n mentioned above, if its `collapsed` property is `false`, it's\\r\\n displayed when the conditions no longer apply.\\r\\n\\r\\n To set the `collapsed` property on an element, use the element's\\r\\n [`collapse()`](#collapse) and [`expand()`](#expand) functions.\\r\\n\\r\\n If you select **Collapsed on load** in the element's Properties panel\\r\\n in the Editor, the `collapsed` property is set to `true` when the page loads.\"},{\"name\":\"deleted\",\"slug\":\"deleted\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get an element's deleted status\",\"content\":\"const isDeleted = $w(\\\"#myElement\\\").deleted;  // true\"},{\"title\":\"Toggle an element's deleted state\",\"content\":\"if( $w(\\\"#myElement\\\").deleted ) {\\n  $w(\\\"#myElement\\\").restore();\\n}\\nelse {\\n  $w(\\\"#myElement\\\").delete();\\n}\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if an element was temporarily deleted from the [DOM](https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction).\\r\\nUse the [`restore`](#restore) function to restore the deleted element.\\r\\n\\r\\nIf `deleted` is `true`, the element is not in the current DOM.\\r\\n\\r\\n If `deleted` is `false` the element is in the current DOM.\\r\\n\\r\\n\u003e**Notes:**\\r\\n\u003e - An element whose `deleted` status is `true` can be edited.\\r\\n\u003e - In Wix Studio, an element whose `deleted` status is `false` will not be displayed if the element has been set to **Hide**.\"},{\"name\":\"global\",\"slug\":\"global\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if an element appears on all pages or only on the current page.\\r\\n\\r\\nIf `global` is `true`, the element appears on all pages.\\r\\n\\r\\n If `global` is `false`, the element only appears on the current page.\"},{\"name\":\"hidden\",\"slug\":\"hidden\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if the element is visible or hidden.\\r\\n\\r\\nIf `hidden` is `true`, the element is not displayed on the page under\\r\\n any circumstances. However, the hidden element is still in the site's DOM. Unlike a\\r\\n `collapsed` element, a hidden element continues to\\r\\n take up the same space on the page as it did when it was visible.\\r\\n\\r\\n If `hidden` is `false`, the element _may_ be displayed on the page.\\r\\n\\r\\n However, an element whose `hidden` property is `false` is still not\\r\\n displayed if:\\r\\n\\r\\n + It is `collapsed`.\\r\\n + Its parent element is hidden or collapsed.\\r\\n + It is a slide in a [Slideshow]($w.Slideshow.html) which is\\r\\n   currently not being displayed.\\r\\n + In Wix Studio, it has been set to **Hide** for the current breakpoint.\\r\\n\\r\\n\\r\\n Even if the element is not displayed due to the conditions\\r\\n mentioned above, if its `hidden` property is set to `false`, it's\\r\\n displayed when the conditions no longer apply.\\r\\n\\r\\n To determine if the element is actually visible, use the\\r\\n [`isVisible`](#isVisible) property.\\r\\n\\r\\n To set the `hidden` property on an element, use the element's\\r\\n [`hide()`](#hide) or [`show()`](#show) functions.\\r\\n\\r\\n If you select **Hidden** in the Properties and Events panel\\r\\n in the Editor, the `hidden` property is set to `true` when the page loads.\\r\\n\\r\\n \u003e **Note:** An element's `hidden` property is not the same as its\\r\\n  [isVisible](#isVisible) property. The `hidden` property\\r\\n  indicates whether the element _should_ be displayed, while `isVisible`\\r\\n  indicates if it is actually displayed.\"},{\"name\":\"id\",\"slug\":\"id\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the element's ID.\\r\\n\\r\\nThe ID is the element's unique identifier. It is used when selecting\\r\\n elements using the [`$w()`]($w.html#$w) function.\\r\\n\\r\\n An element's `id` is set in the Editor using the [Properties panel](https://support.wix.com/en/article/how-do-i-use-the-properties-panel).\"},{\"name\":\"isVisible\",\"slug\":\"is-visible\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if the element is actually visible.\\r\\n\\r\\nIf `isVisible` is `true`, the element is displayed on the page.\\r\\n\\r\\n If `isVisible` is `false`, the element is not displayed on the page.\\r\\n\\r\\n The value of the `isVisible` property is calculated based on the\\r\\n `hidden`, `collapsed`, `rendered`, \\r\\n and `deleted` properties of the element and all of its ancestors. \\r\\n `isVisible` is `true` only the element is displayed on the page. \\r\\n This means that for the element and its ancestors, `rendered` is `true` and `hidden`, \\r\\n `collapsed`, and `deleted` are `false`.\\r\\n\\r\\n\u003e **Notes:** \\r\\n\u003e + An element's `isVisible` property is not the same as its\\r\\n\u003e   `hidden` property. The `isVisible` property\\r\\n\u003e   indicates whether the element is actually displayed, while `hidden`\\r\\n\u003e   indicates if it _should_ be displayed.\\r\\n\u003e\\r\\n\u003e\\r\\n\u003e + The `isVisible` property of an element remains `true` even if\\r\\n\u003e   another element completely covers it so that a user cannot see it.\\r\\n\u003e\\r\\n\u003e\\r\\n\u003e + In Wix Studio, even if the `isVisible` property of the element is `true`, it will not be displayed if the element has been set to **Hide** for the current breakpoint in the Layers more actions menu.\"},{\"name\":\"parent\",\"slug\":\"parent\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"Node\",\"referenceFqn\":\"Node.Node\"},\"description\":\"Gets the element's parent element.\\r\\n\\r\\nSome elements can contain other elements. This occurs when you drag\\r\\n an element onto a container element. The container is the `parent` of\\r\\n all the elements it contains.\\r\\n\\r\\n [`Page`]($w.Page.html), [`Header`]($w.Header.html), and\\r\\n [`Footer`]($w.Footer.html) are top-level elements and have no parent.\"},{\"name\":\"rendered\",\"slug\":\"rendered\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get an element's rendered status\",\"content\":\"let isRendered = $w(\\\"#myElement\\\").rendered;  // true\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if an element is currently in the [DOM structure](https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction).\\r\\n\\r\\nIf `rendered` is `true`, the element is in the current DOM structure and\\r\\n can be used.\\r\\n\\r\\n If `rendered` is `false` the element is not in the current DOM structure.\\r\\n\\r\\n An element might not be in the DOM if it is in a [slide]($w.Slide.html) or a [state]($w.State.html)\\r\\n which is not currently showing.\"},{\"name\":\"type\",\"slug\":\"type\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the element's type.\\r\\n\\r\\nPossible values include:\\r\\n\\r\\n - `$w.TextInput`\\r\\n - `$w.TextBox`\\r\\n - `$w.RichTextBox`\\r\\n - `$w.RadioButtonGroup`\\r\\n - `$w.CheckboxGroup`\\r\\n - `$w.Dropdown`\\r\\n - `$w.SelectionTags`\\r\\n - `$w.Slider`\\r\\n - `$w.DatePicker`\\r\\n - `$w.UploadButton`\\r\\n - `$w.RatingsInput`\\r\\n - `$w.AddressInput`\\r\\n - `$w.Switch`\\r\\n - `$w.SignatureInput`\\r\\n - `$w.Captcha`\"},{\"name\":\"enabled\",\"slug\":\"enabled\",\"isReadOnly\":true,\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"examples\":[{\"title\":\"Get an element's enabled status\",\"content\":\"let isEnabled = $w(\\\"#myElement\\\").enabled; // true\"},{\"title\":\"Toggle an element's enabled state\",\"content\":\"if( $w(\\\"#myElement\\\").enabled ) {\\n  $w(\\\"#myElement\\\").disable();\\n}\\nelse {\\n  $w(\\\"#myElement\\\").enable();\\n}\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"boolean\"},\"description\":\"Indicates if the element is enabled or disabled.\\r\\n\\r\\nIf `enabled` is `true`, users can interact with the element.\\r\\n\\r\\n If `enabled` is `false`, users cannot interact with the element.\\r\\n\\r\\n When an element is disabled:\\r\\n\\r\\n + Its color is faded or grayed out.\\r\\n + Animations that the element normally exhibits when being interacting\\r\\n   with do not occur.\\r\\n + Actions that the element has been configured to perform, such as\\r\\n   opening a link, do not occur.\\r\\n + Event handlers that have been bound to the element, such as with\\r\\n   `onMouseIn`, do not run.\\r\\n + If the element is an input element, such as a dropdown or text box,\\r\\n   users cannot interact with it.\\r\\n\\r\\n\\r\\n To set the `enabled` property of an element, use the element's\\r\\n [`enable()`](#enable) or [`disable()`](#disable) functions.\\r\\n\\r\\n The `enabled` property can also be set in the Editor using the Properties and Events panel.\"}]},{\"name\":\"DashboardNumberInput\",\"slug\":\"dashboard-number-input\",\"fqn\":\"DashboardNumberInput\",\"standaloneTypes\":[],\"metadata\":{},\"actions\":[{\"name\":\"onKeyPress\",\"fqn\":\"DashboardNumberInput.onKeyPress\",\"slug\":\"on-key-press\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"eventHandler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"REFERENCE\",\"name\":\"Element\",\"referenceFqn\":\"Element.Element\",\"description\":\"The element on which the event is now registered.\"},\"examples\":[{\"title\":\"Get the key that was pressed\",\"content\":\"$w('myElement').onKeyPress( (event) =\u003e {\\n  let key = event.key;  // \\\"a\\\"\\n} );\"},{\"title\":\"Get all of the keyboard event's properties\",\"content\":\"$w(\\\"#myElement\\\").onKeyPress( (event) =\u003e {\\n  let key  = event.key;                 // \\\"A\\\"\\n  let shift = event.shiftKey;           // true\\n  let meta = event.metaKey;             // false\\n  let alt = event.altKey;               // false\\n  let ctrl = event.ctrlKey;             // false\\n  let value = event.target.value;       // string value of text inside \\\"#myElement\\\" before the last KeyPress event\\n} );\"}],\"actionParams\":[{\"name\":\"eventHandler\",\"slug\":\"event-handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"KeyboardEventHandler\",\"referenceFqn\":\"KeyboardEventHandler\",\"isFunction\":true},\"description\":\"The name of the function or\\r\\n the function expression to run when a key is pressed.\"}],\"description\":\"Adds an event handler that runs when a key is pressed within\\r\\nthe input field.\\r\\n\\r\\nA dashboard number input element receives a `keyPress` event when a user presses a key on\\r\\n the keyboard while the cursor is inside the input element. A `keyPress`\\r\\n event is fired for printable and non-printable characters.\\r\\n\\r\\n\u003e **Notes:**\\r\\n\u003e + Some browsers do not issue a key press event for certain keys,\\r\\n\u003e   such as arrow keys or the shift key.\\r\\n\u003e\\r\\n\u003e\\r\\n\u003e + When you retrieve the `value` from the `target` property of a [`KeyboardEvent`]($w.KeyboardEvent.html),\\r\\n\u003e   you get the value of the target element before the key was pressed.\",\"sdkErrors\":[]},{\"name\":\"onKeyRelease\",\"fqn\":\"DashboardNumberInput.onKeyRelease\",\"slug\":\"on-key-release\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\"