n        let fieldValue = firstItem.fieldName;\\n      } )\\n      .catch( (err) =\u003e {\\n        let errMsg = err.message;\\n        let errCode = err.code;\\n      } );\\n\\n  } );\\n\\n} );\"}],\"actionParams\":[{\"name\":\"pageIndex\",\"slug\":\"page-index\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"number\"},\"description\":\"The index of the page to load.\"}],\"description\":\"Loads the specified page.\\r\\n\\r\\nThe `loadPage()` function returns a Promise that is resolved to\\r\\n an array of the specified [page](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages)'s items when:\\r\\n\\r\\n + The current item is saved in the collection (if necessary).\\r\\n + The specified [page of data](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages) is loaded.\\r\\n + Any connected elements have been updated with the new data.\\r\\n + The current item is updated to the first item in the loaded page.\\r\\n\\r\\n\\r\\n The indices of the dataset's [pages](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages) start at `1`.\\r\\n\\r\\n\u003e **Notes:**\\r\\n \u003e + A dataset needs to load its data before you call its `loadPage()` function.\\r\\n \u003e\\r\\n \u003e     Usually a dataset finishes loading a short time after the page it is on finishes loading. So if you call `loadPage()` inside the page’s [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready) event handler, the dataset might not be ready yet.\\r\\n \u003e\\r\\n\u003e    To call `loadPage()` as soon as possible after a page loads, use the **dataset's** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/on-ready) function inside the **page’s** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready) event handler to ensure that both the page and the dataset have finished loading.\\r\\n \u003e + When using a read-write dataset and linked input elements, calling any of the following functions will save any changes made in the linked input elements.\\r\\n\u003e    + [setFilter()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-filter)\\r\\n\u003e    + [setSort()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-sort)\\r\\n\u003e    + [nextPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/next-page)\\r\\n\u003e    + [previousPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/previous-page)\\r\\n\u003e    + [loadPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/load-page)\\r\\n\u003e    + [setPageSize()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-page-size)\\r\\n\u003e    + [setCurrentItemIndex()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-current-item-index)\\r\\n\u003e    + [next()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/next)\\r\\n\u003e    + [previous()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/previous)\\r\\n\u003e    + [save()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/save)\",\"sdkErrors\":[]},{\"name\":\"new\",\"fqn\":\"Dataset.new\",\"slug\":\"new\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"description\":\"Fulfilled - When a new empty item is the current item of the dataset.\\r\\nRejected - An error message.\"},\"examples\":[{\"title\":\"Save the current item and create a new blank item\",\"content\":\"// NOTE: This example uses the new add() \\n//       function, which replaces new().  \\n//       See the function description for more information, and \\n//       line 14 for the deprecated example.\\n\\n$w(\\\"#myDataset\\\").add()\\n  .then( ( ) =\u003e {\\n    console.log(\\\"New item created\\\");\\n  } )\\n  .catch( (err) =\u003e {\\n    let errMsg = err;\\n  } );\\n\\n// NOTE: This example uses the deprecated new() function.\\n\\n  $w(\\\"#myDataset\\\").new()\\n  .then( ( ) =\u003e {\\n    console.log(\\\"New item created\\\");\\n  } )\\n  .catch( (err) =\u003e {\\n    let errMsg = err;\\n  } );\"},{\"title\":\"Save the current item and create a new blank item when the page loads\",\"content\":\"// NOTE: This example uses the new add() \\n//       function, which replaces new().  \\n//       See the function description for more information, and \\n//       line 20 for the deprecated example.\\n\\n$w.onReady( () =\u003e {\\n  $w(\\\"#myDataset\\\").onReady( () =\u003e {\\n    $w(\\\"#myDataset\\\").add()\\n      .then( ( ) =\u003e {\\n        console.log(\\\"New item created\\\");\\n      } )\\n      .catch( (err) =\u003e {\\n        let errMsg = err;\\n      } );\\n\\n  } );\\n  \\n} );\\n\\n// NOTE: This example uses the deprecated new() function.\\n\\n$w.onReady( () =\u003e {\\n  $w(\\\"#myDataset\\\").onReady( () =\u003e {\\n    $w(\\\"#myDataset\\\").new()\\n      .then( ( ) =\u003e {\\n        console.log(\\\"New item created\\\");\\n      } )\\n      .catch( (err) =\u003e {\\n        let errMsg = err;\\n      } );\\n\\n  } );\\n  \\n} );\"}],\"description\":\"**Deprecated.**\\r\\nThis function will continue to work, but a newer version is available. Use the\\r\\n[`add()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/add) function instead.\\r\\n\\r\\nCreates a new blank item.\\r\\n\\r\\n The `new()` function saves the current item and then creates a new blank\\r\\n item. When the editing of the new item is complete, you will need to\\r\\n call another function that will save the new item.\\r\\n\\r\\n The index of the new item is one after the index of the current item, or\\r\\n zero if there is no current item.\\r\\n\\r\\n Note that since the `new()` function begins by saving the current item,\\r\\n if the current item cannot be saved for any reason, such as it does not\\r\\n pass validation, calling the function will cause an error.\\r\\n\\r\\n Calling `new()` on a read-only dataset causes an error.\\r\\n\\r\\n \u003e **Note:**\\r\\n \u003e\\r\\n \u003e A dataset needs to load its data before you call its `new()` function.\\r\\n \u003e Usually a dataset finishes loading a short time after the page it is on finishes\\r\\n \u003e loading. So if you call `new()` inside the page’s [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready)\\r\\n \u003e event handler, the dataset might not be ready yet.\\r\\n \u003e\\r\\n \u003e To call `new()` as soon as possible after a page loads, use the **dataset's**\\r\\n \u003e [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/on-ready) function inside the **page’s** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready)\\r\\n \u003e event handler to ensure that both the page and the dataset have finished loading.\",\"sdkErrors\":[]},{\"name\":\"next\",\"fqn\":\"Dataset.next\",\"slug\":\"next\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"PRIMITIVE\",\"name\":\"object\"},\"description\":\"Fulfilled - The next item in the dataset.\\r\\nRejected - An error message.\"},\"examples\":[{\"title\":\"Move to the next item\",\"content\":\"$w(\\\"#myDataset\\\").next()\\n  .then( (item) =\u003e {\\n    let fieldValue = item.fieldName;\\n  } )\\n  .catch( (err) =\u003e {\\n    let errMsg = err;\\n  } );\"},{\"title\":\"Move to the next item when the page loads\",\"content\":\"$w.onReady( () =\u003e {\\n  $w(\\\"#myDataset\\\").onReady( () =\u003e {\\n    $w(\\\"#myDataset\\\").next()\\n      .then( (item) =\u003e {\\n        let fieldValue = item.fieldName;\\n      } )\\n      .catch( (err) =\u003e {\\n        let errMsg = err;\\n      } );\\n\\n  } );\\n  \\n} );\"}],\"description\":\"Saves the current item and moves to the next item.\\r\\n\\r\\nThe `next()` function returns a Promise that is resolved to the next item\\r\\n when:\\r\\n\\r\\n + The current item is saved in the collection (if necessary).\\r\\n + Any connected page elements have been updated with the new current item’s values.\\r\\n\\r\\n\\r\\n Calling `next()` on a write-only dataset causes the\\r\\n Promise to reject.\\r\\n\\r\\n If the dataset is read-write, the current item is saved even if there is\\r\\n no next item.\\r\\n\\r\\n \u003e **Notes:**\\r\\n \u003e + A dataset needs to load its data before you call its `next()` function.\\r\\n \u003e\\r\\n \u003e     Usually a dataset finishes loading a short time after the page it is on finishes loading. So if you call `next()` inside the page’s [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready) event handler, the dataset might not be ready yet.\\r\\n \u003e\\r\\n\u003e    To call `next()` as soon as possible after a page loads, use the **dataset's** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/on-ready) function inside the **page’s** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready) event handler to ensure that both the page and the dataset have finished loading.\\r\\n \u003e + When using a read-write dataset and linked input elements, calling any of the following functions will save any changes made in the linked input elements.\\r\\n\u003e    + [setFilter()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-filter)\\r\\n\u003e    + [setSort()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-sort)\\r\\n\u003e    + [nextPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/next-page)\\r\\n\u003e    + [previousPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/previous-page)\\r\\n\u003e    + [loadPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/load-page)\\r\\n\u003e    + [setPageSize()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-page-size)\\r\\n\u003e    + [setCurrentItemIndex()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-current-item-index)\\r\\n\u003e    + [next()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/next)\\r\\n\u003e    + [previous()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/previous)\\r\\n\u003e    + [save()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/save)\",\"sdkErrors\":[]},{\"name\":\"nextPage\",\"fqn\":\"Dataset.nextPage\",\"slug\":\"next-page\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"ARRAY\",\"elementType\":{\"kind\":\"PRIMITIVE\",\"name\":\"object\"}},\"description\":\"Fulfilled - When the next page of data has been loaded and any connected elements have been updated.\\r\\nRejected - An error message.\"},\"examples\":[{\"title\":\"Move to the next page of dataset content\",\"content\":\"$w(\\\"#myDataset\\\").nextPage()\\n  .then( (items) =\u003e {\\n    let firstItem = items[0];\\n    let fieldValue = firstItem.fieldName;\\n  } )\\n  .catch( (err) =\u003e {\\n    let errMsg = err.message;\\n    let errCode = err.code;\\n  } );\"},{\"title\":\"Move to the next page of dataset content when the page loads\",\"content\":\"$w.onReady( () =\u003e {\\n  $w(\\\"#myDataset\\\").onReady( () =\u003e {\\n    $w(\\\"#myDataset\\\").nextPage()\\n      .then( (items) =\u003e {\\n        let firstItem = items[0];\\n        let fieldValue = firstItem.fieldName;\\n      } )\\n      .catch( (err) =\u003e {\\n        let errMsg = err.message;\\n        let errCode = err.code;\\n      } );\\n\\n  } );\\n\\n} );\"}],\"description\":\"Moves to the next page of data.\\r\\n\\r\\nThe `nextPage()` function returns a Promise that is resolved to\\r\\n an array of the next [page](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages)'s items when:\\r\\n\\r\\n + The current item is saved in the collection (if necessary).\\r\\n + The next [page of data](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages) is loaded.\\r\\n + Any connected elements have been updated with the new data.\\r\\n + The current item is updated to the first item in the next page.\\r\\n\\r\\n\\r\\n Going to the next [page of data](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages) replaces the current items\\r\\n in any connected elements with the new items that correspond to the\\r\\n next [page of data](https://dev.wix.com/docs/velo/api-reference/$w/dataset/introduction#dataset-pages). Elements that have their own settings for how many items\\r\\n are shown at once, such as tables and galleries, are not affected.\\r\\n\\r\\n Calling `nextPage()` on a write-only dataset causes an error.\\r\\n \u003e **Notes:**\\r\\n \u003e + A dataset needs to load its data before you call its `nextPage()` function.\\r\\n \u003e\\r\\n \u003e     Usually a dataset finishes loading a short time after the page it is on finishes loading. So if you call `nextPage()` inside the page’s [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready) event handler, the dataset might not be ready yet.\\r\\n \u003e\\r\\n\u003e    To call `nextPage()` as soon as possible after a page loads, use the **dataset's** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/on-ready) function inside the **page’s** [`onReady()`](https://dev.wix.com/docs/velo/api-reference/$w/on-ready) event handler to ensure that both the page and the dataset have finished loading.\\r\\n \u003e + When using a read-write dataset and linked input elements, calling any of the following functions will save any changes made in the linked input elements.\\r\\n\u003e    + [setFilter()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-filter)\\r\\n\u003e    + [setSort()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-sort)\\r\\n\u003e    + [nextPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/next-page)\\r\\n\u003e    + [previousPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/previous-page)\\r\\n\u003e    + [loadPage()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/load-page)\\r\\n\u003e    + [setPageSize()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-page-size)\\r\\n\u003e    + [setCurrentItemIndex()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/set-current-item-index)\\r\\n\u003e    + [next()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/next)\\r\\n\u003e    + [previous()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/previous)\\r\\n\u003e    + [save()](https://dev.wix.com/docs/velo/api-reference/$w/dataset/save)\",\"sdkErrors\":[]},{\"name\":\"onAfterSave\",\"fqn\":\"Dataset.onAfterSave\",\"slug\":\"on-after-save\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"examples\":[{\"title\":\"Register a callback to run after a save\",\"content\":\"$w(\\\"#myDataset\\\").onAfterSave( () =\u003e {\\n  console.log(\\\"After save\\\")\\n});\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"AfterSaveHandler\",\"referenceFqn\":\"Dataset.AfterSaveHandler\",\"isFunction\":true},\"description\":\"The after save event handler.\"}],\"description\":\"Adds an event handler that runs just after a save.\\r\\n\\r\\nThe `onAfterSave()` function allows you to optionally perform actions\\r\\n right after a [`save()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/save) operation. When you call `save()`, the\\r\\n callback is run after the save has successfully completed.\\r\\n\\r\\n Calling `onAfterSave()` on a read-only dataset causes an error.\",\"sdkErrors\":[]},{\"name\":\"onBeforeSave\",\"fqn\":\"Dataset.onBeforeSave\",\"slug\":\"on-before-save\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"handler\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"PRIMITIVE\",\"name\":\"void\"},\"examples\":[{\"title\":\"Register a callback to run before a save and continue with the save\",\"content\":\"$w(\\\"#myDataset\\\").onBeforeSave( () =\u003e {\\n  console.log(\\\"Continuing save\\\");\\n  return true;\\n} );\"},{\"title\":\"Register a callback to run before a save and cancel the save\",\"content\":\"$w(\\\"#myDataset\\\").onBeforeSave( () =\u003e {\\n  console.log(\\\"Canceling save\\\");\\n  return false;\\n} );\"}],\"actionParams\":[{\"name\":\"handler\",\"slug\":\"handler\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"REFERENCE\",\"name\":\"BeforeSaveHandler\",\"referenceFqn\":\"Dataset.BeforeSaveHandler\",\"isFunction\":true},\"description\":\"The before save event handler.\"}],\"description\":\"Adds an event handler that runs just before a save.\\r\\n\\r\\nThe `onBeforeSave()` function allows you to optionally perform actions\\r\\n right before a [`save()`](https://dev.wix.com/docs/velo/api-reference/$w/dataset/save) operation. When you call `save()`, the\\r\\n callback is run before the save operation. Any validity checks on the\\r\\n data are run after the callback runs. If the callback function\\r\\n returns `false`, returns a rejected Promise, or throws an error, the\\r\\n save operation is canceled.\\r\\n\\r\\n\u003e **Notes:**\\r\\n\u003e  + Calling `onBeforeSave()` on a read-only dataset causes an error.\\r\\n\u003e  + `onBeforeSave()` runs before any input element validations.\",\"sdkErrors\":[]},{\"name\":\"onCurrentIndexChanged\",\"fqn\":\"Dataset.onCurrentIndexChanged\",\"slug\":\"on-current-index-changed\",\"isDeprecat