ment\\\").hide();\\n}\"}],\"actionParams\":[{\"name\":\"effectName\",\"slug\":\"effect-name\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"The name of the\\r\\n effect to play when hiding the item.\"},{\"name\":\"effectOptions\",\"slug\":\"effect-options\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"UNION\",\"types\":[{\"kind\":\"REFERENCE\",\"name\":\"ArcEffectOptions\",\"referenceFqn\":\"EffectOptions.ArcEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"BounceEffectOptions\",\"referenceFqn\":\"EffectOptions.BounceEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FadeEffectOptions\",\"referenceFqn\":\"EffectOptions.FadeEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FlipEffectOptions\",\"referenceFqn\":\"EffectOptions.FlipEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FloatEffectOptions\",\"referenceFqn\":\"EffectOptions.FloatEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FlyEffectOptions\",\"referenceFqn\":\"EffectOptions.FlyEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FoldEffectOptions\",\"referenceFqn\":\"EffectOptions.FoldEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"GlideEffectOptions\",\"referenceFqn\":\"EffectOptions.GlideEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"PuffEffectOptions\",\"referenceFqn\":\"EffectOptions.PuffEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"RollEffectOptions\",\"referenceFqn\":\"EffectOptions.RollEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"SlideEffectOptions\",\"referenceFqn\":\"EffectOptions.SlideEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"SpinEffectOptions\",\"referenceFqn\":\"EffectOptions.SpinEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"TurnEffectOptions\",\"referenceFqn\":\"EffectOptions.TurnEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"ZoomEffectOptions\",\"referenceFqn\":\"EffectOptions.ZoomEffectOptions\"}]},\"description\