e\\\");\"},{\"title\":\"Hide an element with the \\\"fade\\\" effect and custom options\",\"content\":\"let fadeOptions = {\\n  \\\"duration\\\":   2000,\\n  \\\"delay\\\":      1000\\n};\\n\\n$w(\\\"#myElement\\\").hide(\\\"fade\\\", fadeOptions);\"},{\"title\":\"Hide an element with an effect and log a message when the effect is done\",\"content\":\"$w(\\\"#myElement\\\").hide(\\\"fade\\\")\\n  .then( ( ) =\u003e {\\n    console.log(\\\"Done with fade\\\");\\n} );\"},{\"title\":\"Toggle an element's hidden state\",\"content\":\"if( $w(\\\"#myElement\\\").hidden ) {\\n  $w(\\\"#myElement\\\").show();\\n}\\nelse {\\n  $w(\\\"#myElement\\\").hide();\\n}\"}],\"actionParams\":[{\"name\":\"effectName\",\"slug\":\"effect-name\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"The name of the\\r\\n effect to play when hiding the item.\"},{\"name\":\"effectOptions\",\"slug\":\"effect-options\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"UNION\",\"types\":[{\"kind\":\"REFERENCE\",\"name\":\"ArcEffectOptions\",\"referenceFqn\":\"EffectOptions.ArcEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"BounceEffectOptions\",\"referenceFqn\":\"EffectOptions.BounceEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FadeEffectOptions\",\"referenceFqn\":\"EffectOptions.FadeEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FlipEffectOptions\",\"referenceFqn\":\"EffectOptions.FlipEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FloatEffectOptions\",\"referenceFqn\":\"EffectOptions.FloatEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FlyEffectOptions\",\"referenceFqn\":\"EffectOptions.FlyEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"FoldEffectOptions\",\"referenceFqn\":\"EffectOptions.FoldEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":\"GlideEffectOptions\",\"referenceFqn\":\"EffectOptions.GlideEffectOptions\"},{\"kind\":\"REFERENCE\",\"name\":