Get the type of the event\",\"content\":\"$w(\\\"#myElement\\\").onEvent( (event) =\u003e {\\n  let eventType = event.type; // \\\"click\\\"\\n} );\"}],\"type\":{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},\"description\":\"Gets the type of event that was fired.\"}]},{\"name\":\"Tabs\",\"slug\":\"tabs\",\"fqn\":\"Tabs\",\"standaloneTypes\":[],\"metadata\":{},\"actions\":[{\"name\":\"changeTab\",\"fqn\":\"Tabs.changeTab\",\"slug\":\"change-tab\",\"isDeprecated\":false,\"isInternal\":false,\"actionErrors\":[],\"isDeveloperPreview\":false,\"maturity\":\"GA\",\"requiredProperties\":[\"tabReference\"],\"adminMethod\":false,\"returnType\":{\"kind\":\"PROMISE\",\"argumentType\":{\"kind\":\"REFERENCE\",\"name\":\"Tab\",\"referenceFqn\":\"Tab.Tab\"},\"description\":\"Fulfilled - The tab that the tabs element changed to.\"},\"examples\":[{\"title\":\"Move to a different tab using an ID\",\"content\":\"$w(\\\"#myTabsElement\\\").changeTab(\\\"singleTab2\\\");\"},{\"title\":\"Move to a different tab using a tab element\",\"content\":\"let myNewTab = $w(\\\"#singleTab2\\\");\\n\\n$w(\\\"#myTabsElement\\\").changeTab(myNewTab);\"},{\"title\":\"Move to a different tab and log a message when the move is finished\",\"content\":\"$w(\\\"#myTabsElement\\\").changeTab(\\\"singleTab2\\\")\\n  .then((newTab) =\u003e {\\n    console.log(`Done moving to ${newTab.id}`);\\n  });\"},{\"title\":\"Get the list of tabs in a tabs element and move to one of the tabs\",\"content\":\"let myTabs = $w(\\\"#myTabsElement\\\").tabs;\\nlet numberOfTabs = myTabs.length; // 3\\n\\nlet myNewTab = myTabs[2];\\n$w(\\\"#myTabsElement\\\").changeTab(myNewTab);\\n\\nlet myCurrentTab = $w(\\\"#myTabsElement\\\").currentTab;\\nlet myCurrentTabLabel = myCurrentTab.label; // \\\"Third Tab\\\"\"}],\"actionParams\":[{\"name\":\"tabReference\",\"slug\":\"tab-reference\",\"isDeprecated\":false,\"isInternal\":false,\"maturity\":\"GA\",\"type\":{\"kind\":\"UNION\",\"types\":[{\"kind\":\"PRIMITIVE\",\"name\":\"string\"},{\